mapper.select:
SELECT id, article_id, ip_address, create_by, update_by, create_time, update_time, deleted
FROM article_likes
WHERE article_id = #{articleId}
  AND create_by = #{userId}

SELECT id, article_id, ip_address, create_by, update_by, create_time, update_time, deleted
FROM article_likes
WHERE article_id = #{articleId}
  AND ip_address = #{ipAddress}
  AND create_by IS NULL

mapper.update:
UPDATE article_likes
SET deleted = 0, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE article_likes
SET deleted = 1, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
